async fn execute_github_pr_merge(plan: GitHubPrMergePlan) -> anyhow::Result<Value> {
    tokio::task::spawn_blocking(move || -> anyhow::Result<Value> {
        let gh = resolve_system_gh_binary()
            .context("System `gh` CLI binary is required to merge GitHub Pull Requests")?;
        let pr_str = plan.pr_number.to_string();
        let method_flag = match plan.method.as_str() {
            "merge" => "--merge",
            "rebase" => "--rebase",
            _ => "--squash",
        };
        let mut gh_args = vec![
            "pr",
            "merge",
            pr_str.as_str(),
            "-R",
            plan.repo.as_str(),
            method_flag,
        ];
        if plan.delete_branch {
            gh_args.push("--delete-branch");
        }
        if let Some(ref subject) = plan.subject {
            gh_args.push("--subject");
            gh_args.push(subject.as_str());
        }
        if let Some(ref body) = plan.body {
            gh_args.push("--body");
            gh_args.push(body.as_str());
        }
        let out = run_sanitized_gh(&gh, &gh_args)?;
        if !out.status.success() {
            bail!(
                "gh pr merge #{} on '{}' failed: {}",
                plan.pr_number,
                plan.repo,
                redact_ci_log_secrets(String::from_utf8_lossy(&out.stderr).trim())
            );
        }
        let msg = redact_ci_log_secrets(String::from_utf8_lossy(&out.stdout).trim());
        Ok(json!({
            "status": "pr_merged",
            "repo": plan.repo,
            "pr_number": plan.pr_number,
            "method": plan.method,
            "delete_branch": plan.delete_branch,
            "message": msg,
            "evidence_hash": plan.evidence_hash,
        }))
    })
    .await?
}

const PKG_MANIFEST_FILES: &[&str] = &[
    "package.json",
    "package-lock.json",
    "pnpm-lock.yaml",
    "yarn.lock",
    "bun.lockb",
    "bun.lock",
    "pyproject.toml",
    "requirements.txt",
    "uv.lock",
    "Cargo.toml",
    "Cargo.lock",
    "go.mod",
    "go.sum",
];

#[derive(Clone)]
pub struct HostExecBrokerConfig {
    pub session_dir: PathBuf,
    pub host_home: PathBuf,
    pub clean_host_path: String,
    pub host_workspace_root: PathBuf,
    pub on_run_finished: Option<Arc<dyn Fn() + Send + Sync>>,
}

impl std::fmt::Debug for HostExecBrokerConfig {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("HostExecBrokerConfig")
            .field("session_dir", &self.session_dir)
            .field("host_home", &self.host_home)
            .field("host_workspace_root", &self.host_workspace_root)
            .finish_non_exhaustive()
    }
}

#[derive(Debug, Clone)]
struct HostExecStagedInput {
    sha256: String,
    executable: bool,
}

#[derive(Debug, Clone)]
struct HostExecPlan {
    config: HostExecBrokerConfig,
    resolved_program: PathBuf,
    script_rel: Option<String>,
    args: Vec<String>,
    inputs: std::collections::BTreeMap<String, HostExecStagedInput>,
    output_files: Vec<String>,
    pass_env_kv: std::collections::BTreeMap<String, String>,
    timeout_ms: u64,
    frozen_dir: PathBuf,
    evidence_hash: String,
}

struct HostExecRunGuard {
    active_runs: Arc<std::sync::atomic::AtomicUsize>,
    paas: Arc<PaasControlPlane>,
    on_run_finished: Option<Arc<dyn Fn() + Send + Sync>>,
}

impl Drop for HostExecRunGuard {
    fn drop(&mut self) {
        self.paas.rotate_ephemeral_admin_secret_if_dynamic();
        if let Some(ref cb) = self.on_run_finished {
            cb();
        }
        self.active_runs
            .fetch_sub(1, std::sync::atomic::Ordering::SeqCst);
    }
}

#[cfg(unix)]
struct ProcessGroupReaper(Option<libc::pid_t>);

#[cfg(unix)]
impl Drop for ProcessGroupReaper {
    fn drop(&mut self) {
        if let Some(pgid) = self.0.take() {
            if pgid > 0 {
                unsafe {
                    let _ = libc::killpg(pgid, libc::SIGKILL);
                }
            }
        }
    }
}

struct RunDirCleanupGuard(PathBuf);

impl Drop for RunDirCleanupGuard {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

#[derive(Debug, Clone)]
struct PkgInstallPlan {
    manager: String,
    packages: Vec<String>,
    cwd_rel: String,
    target_dir: PathBuf,
    shadow_root: PathBuf,
    host_root: PathBuf,
    agent_home_dir: PathBuf,
    org_shared_ro_dir: PathBuf,
    org_agent_pub_dir: PathBuf,
    dev: bool,
    allow_scripts: bool,
    offline: bool,
    timeout_ms: u64,
    registry_domains: Vec<String>,
    pre_manifest_hashes: std::collections::BTreeMap<String, String>,
    evidence_hash: String,
}

struct ProxyAbortGuard(Option<tokio::task::JoinHandle<()>>);

impl Drop for ProxyAbortGuard {
    fn drop(&mut self) {
        if let Some(handle) = self.0.take() {
            handle.abort();
        }
    }
}

fn is_safe_package_spec(spec: &str) -> bool {
    if spec.is_empty() || spec.len() > 160 || spec.trim() != spec {
        return false;
    }
    let Some(first) = spec.chars().next() else {
        return false;
    };
    if !(first.is_ascii_alphanumeric() || first == '@') {
        return false;
    }
    if spec.contains("..")
        || spec.contains("://")
        || spec.contains("git+")
        || spec.contains("file:")
        || spec.contains("ssh:")
    {
        return false;
    }
    spec.chars().all(|c| {
        c.is_ascii()
            && !c.is_control()
            && !c.is_whitespace()
            && !matches!(
                c,
                ';' | '|' | '&' | '$' | '`' | '(' | ')' | '{' | '}' | '<' | '>' | '\\' | '\'' | '"' | '?' | '#'
            )
    })
}

fn hash_pkg_manifests(target_dir: &Path) -> anyhow::Result<std::collections::BTreeMap<String, String>> {
    let mut hashes = std::collections::BTreeMap::new();
    for name in PKG_MANIFEST_FILES {
        let p = target_dir.join(name);
        match std::fs::symlink_metadata(&p) {
            Ok(meta) if meta.file_type().is_symlink() => {
                bail!(
                    "Refusing package operation: manifest '{}' is a symlink",
                    p.display()
                );
            }
            Ok(meta) if meta.is_file() => {
                let bytes = std::fs::read(&p)?;
                hashes.insert((*name).to_string(), format!("sha256:{}", hex::encode(Sha256::digest(&bytes))));
            }
            Ok(_) => {
                hashes.insert((*name).to_string(), "NON_FILE".to_string());
            }
            Err(_) => {
                hashes.insert((*name).to_string(), "ABSENT".to_string());
            }
        }
    }
    Ok(hashes)
}

async fn execute_pkg_install(
    identity: &AgentIdentity,
    plan: PkgInstallPlan,
) -> anyhow::Result<Value> {
    let current_hashes = hash_pkg_manifests(&plan.target_dir)?;
    if current_hashes != plan.pre_manifest_hashes {
        bail!(
            "TOCTOU integrity error: package manifest/lockfile state in '{}' changed after approval",
            plan.cwd_rel
        );
    }

    let cache_root = plan.agent_home_dir.join("deps/cache");
    tokio::fs::create_dir_all(&cache_root).await?;

    let mut env = HashMap::new();
    let (cmd, cmd_args): (String, Vec<String>) = match plan.manager.as_str() {
        "npm" | "pnpm" | "yarn" | "bun" => {
            CoWWorkspace::isolate_shadow_dependency_dir(
                &plan.host_root,
                &plan.shadow_root,
                &plan.target_dir,
                "node_modules",
            )?;
            if plan.target_dir != plan.shadow_root {
                CoWWorkspace::isolate_shadow_dependency_dir(
                    &plan.host_root,
                    &plan.shadow_root,
                    &plan.shadow_root,
                    "node_modules",
                )?;
            }
            let mgr_cache = cache_root.join(&plan.manager);
            let pnpm_store = cache_root.join("pnpm-store");
            let pnpm_home = cache_root.join("pnpm-home");
            let xdg_cache = cache_root.join("xdg-cache");
            let xdg_data = cache_root.join("xdg-data");
            let xdg_state = cache_root.join("xdg-state");
            let yarn_cache = cache_root.join("yarn");
            let bun_cache = cache_root.join("bun");
            for dir in [
                &mgr_cache,
                &pnpm_store,
                &pnpm_home,
                &xdg_cache,
                &xdg_data,
                &xdg_state,
                &yarn_cache,
                &bun_cache,
            ] {
                tokio::fs::create_dir_all(dir).await?;
            }
            let cache_str = mgr_cache.display().to_string();
            let pnpm_store_str = pnpm_store.display().to_string();
            env.insert("NPM_CONFIG_USERCONFIG".to_string(), "/dev/null".to_string());
            env.insert("NPM_CONFIG_CACHE".to_string(), cache_str.clone());
            env.insert("npm_config_cache".to_string(), cache_str);
            env.insert("PNPM_STORE_DIR".to_string(), pnpm_store_str.clone());
            env.insert("npm_config_store_dir".to_string(), pnpm_store_str);
            env.insert("PNPM_HOME".to_string(), pnpm_home.display().to_string());
            env.insert("XDG_CACHE_HOME".to_string(), xdg_cache.display().to_string());
            env.insert("XDG_DATA_HOME".to_string(), xdg_data.display().to_string());
            env.insert("XDG_STATE_HOME".to_string(), xdg_state.display().to_string());
            env.insert("YARN_CACHE_FOLDER".to_string(), yarn_cache.display().to_string());
            env.insert("BUN_INSTALL_CACHE_DIR".to_string(), bun_cache.display().to_string());
            env.insert(
                "npm_config_registry".to_string(),
                "https://registry.npmjs.org/".to_string(),
            );
            env.insert("COREPACK_ENABLE_STRICT".to_string(), "0".to_string());
            env.insert("CI".to_string(), "true".to_string());
            if !plan.allow_scripts {
                env.insert("YARN_ENABLE_SCRIPTS".to_string(), "false".to_string());
            }

            let mut mgr_args: Vec<String> = match plan.manager.as_str() {
                "npm" => {
                    let mut a = vec![
                        "install".to_string(),
                        "--no-audit".to_string(),
                        "--no-fund".to_string(),
                    ];
                    if plan.dev && !plan.packages.is_empty() {
                        a.push("--save-dev".to_string());
                    }
                    a
                }
                _ => {
                    if plan.packages.is_empty() {
                        vec!["install".to_string()]
                    } else {
                        let mut a = vec!["add".to_string()];
                        if plan.dev {
                            a.push("-D".to_string());
                        }
                        a
                    }
                }
            };
            if !plan.allow_scripts {
                mgr_args.push("--ignore-scripts".to_string());
            }
            if plan.offline {
                mgr_args.push("--offline".to_string());
            }
            mgr_args.extend(plan.packages.iter().cloned());

            let mut sh_args = vec![
                "-c".to_string(),
                r#"cmd="$1"; shift; exec "$cmd" "$@""#.to_string(),
                "aegis-pkg".to_string(),
                plan.manager.clone(),
            ];
            sh_args.extend(mgr_args);
            ("sh".to_string(), sh_args)
        }
        "pip" | "uv" => {
            CoWWorkspace::isolate_shadow_dependency_dir(
                &plan.host_root,
                &plan.shadow_root,
                &plan.target_dir,
                ".venv",
            )?;
            let mgr_cache = cache_root.join(&plan.manager);
            tokio::fs::create_dir_all(&mgr_cache).await?;
            let cache_str = mgr_cache.display().to_string();
            env.insert("PIP_CONFIG_FILE".to_string(), "/dev/null".to_string());
            env.insert("PIP_CACHE_DIR".to_string(), cache_str.clone());
            env.insert("UV_CACHE_DIR".to_string(), cache_str);
            env.insert("UV_NO_CONFIG".to_string(), "1".to_string());
            env.insert(
                "PIP_INDEX_URL".to_string(),
                "https://pypi.org/simple".to_string(),
            );
            env.insert(
                "UV_INDEX_URL".to_string(),
                "https://pypi.org/simple".to_string(),
            );

            let mut py_args = Vec::new();
            let script = if plan.manager == "pip" {
                if plan.offline {
                    py_args.push("--no-index".to_string());
                }
                if !plan.allow_scripts {
                    py_args.push("--only-binary=:all:".to_string());
                }
                if plan.packages.is_empty() {
                    if plan.target_dir.join("requirements.txt").is_file() {
                        py_args.extend(["-r".to_string(), "requirements.txt".to_string()]);
                    } else {
                        py_args.push(".".to_string());
                    }
                } else {
                    py_args.extend(plan.packages.iter().cloned());
                }
                "if [ ! -x .venv/bin/python ]; then python3 -m venv .venv; fi; exec .venv/bin/pip install \"$@\""
            } else {
                if plan.offline {
                    py_args.push("--offline".to_string());
                }
                if plan.packages.is_empty() {
                    if plan.target_dir.join("requirements.txt").is_file() {
                        py_args.extend([
                            "--python".to_string(),
                            ".venv/bin/python".to_string(),
                            "-r".to_string(),
                            "requirements.txt".to_string(),
                        ]);
                        "if [ ! -x .venv/bin/python ]; then uv venv .venv; fi; exec uv pip install \"$@\""
                    } else {
                        "if [ ! -x .venv/bin/python ]; then uv venv .venv; fi; exec uv sync \"$@\""
                    }
                } else {
                    py_args.extend(["--python".to_string(), ".venv/bin/python".to_string()]);
                    py_args.extend(plan.packages.iter().cloned());
                    "if [ ! -x .venv/bin/python ]; then uv venv .venv; fi; exec uv pip install \"$@\""
                }
            };
            let mut sh_args = vec!["-c".to_string(), script.to_string(), "aegis-pkg".to_string()];
            sh_args.extend(py_args);
            ("sh".to_string(), sh_args)
        }
        "cargo" => {
            let cargo_home = plan.agent_home_dir.join("deps/cargo_home");
            tokio::fs::create_dir_all(cargo_home.join("registry")).await?;
            tokio::fs::create_dir_all(cargo_home.join("git")).await?;
            env.insert("CARGO_HOME".to_string(), cargo_home.display().to_string());
            env.insert("CARGO_NET_GIT_FETCH_WITH_CLI".to_string(), "false".to_string());

            let mut sh_args = Vec::new();
            let script = if plan.packages.is_empty() {
                if plan.offline {
                    sh_args.push("--offline".to_string());
                }
                r#"exec cargo fetch "$@""#
            } else {
                if plan.dev {
                    sh_args.push("--dev".to_string());
                }
                if plan.offline {
                    sh_args.push("--offline".to_string());
                }
                sh_args.extend(plan.packages.iter().cloned());
                if plan.offline {
                    r#"cargo add "$@" && cargo fetch --offline"#
                } else {
                    r#"cargo add "$@" && cargo fetch"#
                }
            };
            let mut full_args = vec!["-c".to_string(), script.to_string(), "aegis-pkg".to_string()];
            full_args.extend(sh_args);
            ("sh".to_string(), full_args)
        }
        "go" => {
            let go_path = plan.agent_home_dir.join("deps/go_path");
            let go_mod_cache = go_path.join("pkg/mod");
            let go_cache = cache_root.join("go-build");
            tokio::fs::create_dir_all(&go_mod_cache).await?;
            tokio::fs::create_dir_all(&go_cache).await?;
            env.insert("GOPATH".to_string(), go_path.display().to_string());
            env.insert("GOMODCACHE".to_string(), go_mod_cache.display().to_string());
            env.insert("GOCACHE".to_string(), go_cache.display().to_string());
            env.insert("GOTOOLCHAIN".to_string(), "local".to_string());
            env.insert(
                "GOPROXY".to_string(),
                if plan.offline {
                    "off".to_string()
                } else {
                    "https://proxy.golang.org,direct".to_string()
                },
            );
            env.insert(
                "GOSUMDB".to_string(),
                if plan.offline {
                    "off".to_string()
                } else {
                    "sum.golang.org".to_string()
                },
            );

            let mut go_args = Vec::new();
            if plan.packages.is_empty() {
                go_args.push("mod".to_string());
                go_args.push("download".to_string());
            } else {
                go_args.push("get".to_string());
                go_args.extend(plan.packages.iter().cloned());
            }
            let mut sh_args = vec![
                "-c".to_string(),
                r#"cmd="$1"; shift; exec "$cmd" "$@""#.to_string(),
                "aegis-pkg".to_string(),
                "go".to_string(),
            ];
            sh_args.extend(go_args);
            ("sh".to_string(), sh_args)
        }
        other => bail!("Unsupported package manager '{}'", other),
    };

    let (_proxy_guard, egress_proxy_addr) = if !plan.offline {
        let egress = Arc::new(AegisEgressGateway::new());
        egress
            .allow_domains(&identity.org_id, plan.registry_domains.clone())
            .await;
        let (addr, handle) = egress
            .start_local_proxy_abortable("127.0.0.1:0", Some(identity.clone()))
            .await?;
        (
            Some(ProxyAbortGuard(Some(handle))),
            Some(format!("http://{}", addr)),
        )
    } else {
        (None, None)
    };

    let sbx = NativeOsSandboxDriver
        .create_sandbox(SandboxConfig {
            identity: identity.clone(),
            tier: IsolationTier::NativeOsSandbox,
            limits: ResourceLimits::default(),
            workspace_dir: plan.shadow_root.clone(),
            agent_home_dir: plan.agent_home_dir.clone(),
            org_shared_ro_dir: plan.org_shared_ro_dir.clone(),
            org_agent_pub_dir: plan.org_agent_pub_dir.clone(),
            egress_proxy_addr,
            host_source_dir: Some(plan.host_root.clone()),
            tighten_home_read: true,
            allowed_loopback_ports: Vec::new(),
            isolate_loopback_only: true,
        })
        .await?;

    let out = sbx
        .exec(ExecSpec {
            command: cmd,
            args: cmd_args,
            cwd: Some(plan.target_dir.clone()),
            env,
            timeout_ms: Some(plan.timeout_ms),
            background: false,
        })
        .await?;

    let post_hashes = hash_pkg_manifests(&plan.target_dir).unwrap_or_default();
    let changed_manifests: Vec<String> = post_hashes
        .iter()
        .filter_map(|(k, v)| {
            if plan.pre_manifest_hashes.get(k) != Some(v) {
                Some(k.clone())
            } else {
                None
            }
        })
        .collect();
    let (stdout_redacted, _) = redact_dlp_secrets(&out.stdout);
    let (stderr_redacted, _) = redact_dlp_secrets(&out.stderr);
    let succeeded = out.exit_code == Some(0);

    Ok(json!({
        "status": if succeeded { "pkg_installed" } else { "pkg_install_failed" },
        "manager": plan.manager,
        "cwd": plan.cwd_rel,
        "packages": plan.packages,
        "exit_code": out.exit_code,
        "duration_ms": out.duration_ms,
        "sandbox_profile_used": out.sandbox_profile_used,
        "registry_domains": if plan.offline { Vec::<String>::new() } else { plan.registry_domains },
        "allow_scripts": plan.allow_scripts,
        "offline": plan.offline,
        "changed_manifests": changed_manifests,
        "host_modified": false,
        "stdout": stdout_redacted,
        "stderr": stderr_redacted,
        "evidence_hash": plan.evidence_hash,
    }))
}

const MAX_HOST_EXEC_FILE_BYTES: usize = 8 * 1024 * 1024;
const MAX_HOST_EXEC_TOTAL_INPUT_BYTES: usize = 16 * 1024 * 1024;
const MAX_HOST_EXEC_OUTPUT_HARVEST_BYTES: u64 = 16 * 1024 * 1024;
const MAX_HOST_EXEC_PIPE_BYTES: usize = 65_536;

fn is_forbidden_host_exec_program_name(bin: &str) -> bool {
    matches!(bin, "sudo" | "su" | "doas" | "pkexec" | "env")
}

fn is_interpreter_program(resolved: &Path) -> bool {
    let name = resolved
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    name == "python"
        || name.starts_with("python3")
        || name.starts_with("python2")
        || matches!(
            name.as_str(),
            "node"
                | "nodejs"
                | "deno"
                | "bun"
                | "sh"
                | "bash"
                | "zsh"
                | "dash"
                | "ksh"
                | "fish"
                | "tcsh"
                | "csh"
                | "pwsh"
                | "ruby"
                | "perl"
                | "php"
                | "lua"
                | "luajit"
                | "awk"
                | "gawk"
                | "nawk"
                | "osascript"
                | "swift"
                | "tclsh"
                | "expect"
                | "rscript"
                | "julia"
                | "lldb"
                | "gdb"
        )
}

fn has_disallowed_interpreter_flags(raw_args: &[String]) -> Option<String> {
    for arg in raw_args {
        if arg == "--" {
            break;
        }
        if matches!(
            arg.as_str(),
            "-c" | "-e" | "--eval" | "--print" | "--command" | "-Command" | "-m" | "-"
        ) || arg.starts_with("--eval=")
            || arg.starts_with("--print=")
            || arg.starts_with("--command=")
        {
            return Some(arg.clone());
        }
        if arg.starts_with('-')
            && !arg.starts_with("--")
            && arg.chars().skip(1).any(|c| matches!(c, 'c' | 'e' | 'm'))
        {
            return Some(arg.clone());
        }
    }
    None
}

fn is_forbidden_host_exec_env_key(key: &str) -> bool {
    if key.is_empty()
        || key.len() > 64
        || !key.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_')
        || key.as_bytes()[0].is_ascii_digit()
    {
        return true;
    }
    let up = key.to_ascii_uppercase();
    if matches!(
        up.as_str(),
        "PYTHONPATH"
            | "PYTHONSTARTUP"
            | "PYTHONHOME"
            | "NODE_OPTIONS"
            | "NODE_PATH"
            | "BASH_ENV"
            | "ENV"
            | "ZDOTDIR"
            | "HOME"
            | "PATH"
            | "TMPDIR"
            | "SHELL"
            | "USER"
            | "LOGNAME"
            | "IFS"
            | "LD_PRELOAD"
            | "LD_LIBRARY_PATH"
    ) {
        return true;
    }
    const FORBIDDEN_PREFIXES: &[&str] = &[
        "AOS_",
        "AEGIS_",
        "SSH_",
        "AWS_",
        "GITHUB_",
        "GH_",
        "ANTHROPIC_",
        "OPENAI_",
        "GEMINI_",
        "GOOGLE_",
        "LD_",
        "DYLD_",
        "HTTP_PROXY",
        "HTTPS_PROXY",
        "ALL_PROXY",
        "NO_PROXY",
    ];
    if FORBIDDEN_PREFIXES.iter().any(|p| up.starts_with(p)) {
        return true;
    }
    const FORBIDDEN_TERMS: &[&str] = &[
        "KEY",
        "TOKEN",
        "SECRET",
        "PASSWORD",
        "PASSWD",
        "CREDENTIAL",
        "AUTH",
        "COOKIE",
        "PROXY",
        "SESSION",
    ];
    FORBIDDEN_TERMS.iter().any(|t| up.contains(t))
}

fn is_protected_client_config_rel(norm_rel: &str) -> bool {
    let wrapped = format!("/{}/", norm_rel.trim_matches('/').to_lowercase());
    [
        "/.git/",
        "/.aegis/",
        "/.claude/",
        "/.gemini/",
        "/.codex/",
        "/.cursor/",
        "/.opencode/",
        "/.hermes/",
        "/.agents/hooks.json",
        "/hooks.json",
        "/mcp_config.json",
    ]
    .iter()
    .any(|m| wrapped.contains(m))
}

fn validate_host_exec_binary_candidate(
    cand: &Path,
    canon_shadow: &Path,
    canon_agent_home: &Path,
) -> Option<PathBuf> {
    let raw_s = cand.to_string_lossy();
    if raw_s.contains(".aegis-bin") || raw_s.contains("/.aegis/bin") {
        return None;
    }
    let canon = std::fs::canonicalize(cand).ok()?;
    if canon.starts_with(canon_shadow) || canon.starts_with(canon_agent_home) {
        return None;
    }
    let canon_s = canon.to_string_lossy();
    if canon_s.contains(".aegis-bin") || canon_s.contains("/.aegis/bin") {
        return None;
    }
    let meta = std::fs::metadata(&canon).ok()?;
    if !meta.is_file() {
        return None;
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        if (meta.permissions().mode() & 0o111) == 0 {
            return None;
        }
    }
    Some(canon)
}

fn resolve_host_program(
    raw_program: &str,
    clean_host_path: &str,
    shadow_root: &Path,
    agent_home_dir: &Path,
) -> anyhow::Result<PathBuf> {
    let raw = raw_program.trim();
    if raw.is_empty() || raw.len() > 256 {
        bail!("Invalid host_exec 'program': expected non-empty binary name or path (<= 256 chars)");
    }
    if raw.chars().any(|c| {
        c.is_control()
            || c.is_whitespace()
            || matches!(
                c,
                ';' | '|' | '&' | '$' | '`' | '>' | '<' | '*' | '?' | '~' | '(' | ')' | '{' | '}' | '[' | ']' | '\\'
            )
    }) {
        bail!("Invalid host_exec 'program' '{}': control chars, whitespace, and shell metacharacters are forbidden", raw);
    }
    let raw_bin = Path::new(raw)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or(raw)
        .to_ascii_lowercase();
    if is_forbidden_host_exec_program_name(&raw_bin) {
        bail!("Privilege escalation or wrapper binary '{}' is forbidden for host_exec", raw);
    }

    let canon_shadow =
        std::fs::canonicalize(shadow_root).unwrap_or_else(|_| shadow_root.to_path_buf());
    let canon_agent_home =
        std::fs::canonicalize(agent_home_dir).unwrap_or_else(|_| agent_home_dir.to_path_buf());

    let resolved = if raw.contains('/') {
        if !raw.starts_with('/') {
            bail!(
                "Relative path '{}' is not allowed for host_exec 'program'; pass a bare command name or absolute host binary path",
                raw
            );
        }
        validate_host_exec_binary_candidate(Path::new(raw), &canon_shadow, &canon_agent_home)
            .with_context(|| format!("Executable host binary '{}' not found or resolves into sandbox", raw))?
    } else {
        clean_host_path
            .split(':')
            .filter(|dir| !dir.is_empty() && !dir.contains(".aegis-bin") && !dir.contains("/.aegis/bin"))
            .find_map(|dir| {
                validate_host_exec_binary_candidate(
                    &Path::new(dir).join(raw),
                    &canon_shadow,
                    &canon_agent_home,
                )
            })
            .with_context(|| format!("Executable '{}' not found on clean host PATH", raw))?
    };

    let resolved_bin = resolved
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    if is_forbidden_host_exec_program_name(&resolved_bin) {
        bail!("Resolved binary '{}' is forbidden for host_exec", resolved.display());
    }
    Ok(resolved)
}

fn read_workspace_file_for_host_exec(
    shadow_root: &Path,
    host_root: &Path,
    rel: &Path,
) -> anyhow::Result<(Vec<u8>, bool)> {
    let canon_shadow = std::fs::canonicalize(shadow_root)
        .with_context(|| format!("Shadow root '{}' is unavailable", shadow_root.display()))?;
    let mut cur = canon_shadow;
    let mut shadow_missing = false;
    for comp in rel.components() {
        let std::path::Component::Normal(seg) = comp else {
            bail!("Invalid relative path component in '{}'", rel.display());
        };
        cur.push(seg);
        match std::fs::symlink_metadata(&cur) {
            Ok(meta) => {
                if meta.file_type().is_symlink() {
                    bail!(
                        "Refusing host_exec input '{}' through symlink '{}' in CoW shadow",
                        rel.display(),
                        cur.display()
                    );
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                shadow_missing = true;
                break;
            }
            Err(e) => {
                return Err(anyhow::Error::new(e)
                    .context(format!("Inspecting CoW shadow path '{}'", cur.display())));
            }
        }
    }

    let (canon_file, bytes) = if !shadow_missing {
        open_and_read_no_symlink(shadow_root, rel)?
    } else {
        open_and_read_no_symlink(host_root, rel)?
    };
    if bytes.len() > MAX_HOST_EXEC_FILE_BYTES {
        bail!(
            "host_exec input '{}' ({} bytes) exceeds 8 MiB per-file limit",
            rel.display(),
            bytes.len()
        );
    }
    #[cfg(unix)]
    let executable = {
        use std::os::unix::fs::PermissionsExt;
        std::fs::symlink_metadata(&canon_file)
            .map(|m| (m.permissions().mode() & 0o111) != 0)
            .unwrap_or(false)
    };
    #[cfg(not(unix))]
    let executable = false;
    Ok((bytes, executable))
}

fn ensure_host_exec_dir_0700(dir: &Path) -> anyhow::Result<()> {
    std::fs::create_dir_all(dir)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(dir, std::fs::Permissions::from_mode(0o700));
    }
    Ok(())
}

fn write_frozen_file_0444(
    frozen_dir: &Path,
    rel: &str,
    bytes: &[u8],
    expected_sha256: &str,
) -> anyhow::Result<()> {
    use std::io::Write;
    let rel_path = shadow_relative(rel)?;
    let dst = frozen_dir.join(&rel_path);
    if let Some(parent) = dst.parent() {
        ensure_host_exec_dir_0700(parent)?;
    }
    if let Ok(meta) = std::fs::symlink_metadata(&dst) {
        if meta.file_type().is_symlink() || !meta.file_type().is_file() {
            bail!("Refusing non-regular or symlink frozen artifact '{}'", dst.display());
        }
        let existing = std::fs::read(&dst)?;
        let actual = hex::encode(Sha256::digest(&existing));
        if actual != expected_sha256 {
            bail!(
                "Frozen bundle integrity mismatch for '{}': expected {}, got {}",
                rel,
                expected_sha256,
                actual
            );
        }
        return Ok(());
    }
    let mut opts = std::fs::OpenOptions::new();
    opts.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        opts.mode(0o400);
    }
    let mut f = opts.open(&dst)?;
    f.write_all(bytes)?;
    f.sync_all()?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&dst, std::fs::Permissions::from_mode(0o400))?;
    }
    Ok(())
}

async fn read_bounded_pipe<R: tokio::io::AsyncRead + Unpin>(
    mut reader: Option<R>,
) -> (Vec<u8>, bool) {
    use tokio::io::AsyncReadExt;
    let Some(ref mut r) = reader else {
        return (Vec::new(), false);
    };
    let mut out = Vec::new();
    let mut buf = [0u8; 4096];
    let mut truncated = false;
    loop {
        match r.read(&mut buf).await {
            Ok(0) => break,
            Ok(n) => {
                if out.len() < MAX_HOST_EXEC_PIPE_BYTES {
                    let take = (MAX_HOST_EXEC_PIPE_BYTES - out.len()).min(n);
                    out.extend_from_slice(&buf[..take]);
                    if take < n {
                        truncated = true;
                    }
                } else {
                    truncated = true;
                }
            }
            Err(_) => break,
        }
    }
    (out, truncated)
}

fn harvest_host_exec_outputs(
    work_dir: &Path,
    shadow_root: &Path,
    output_files: &[String],
) -> anyhow::Result<Vec<Value>> {
    use std::io::Read;
    let canon_work = std::fs::canonicalize(work_dir)?;
    let canon_shadow = std::fs::canonicalize(shadow_root)?;
    let mut harvested = Vec::new();
    for rel in output_files {
        let rel_path = shadow_relative(rel)?;
        let mut src_cur = canon_work.clone();
        let mut missing = false;
        for comp in rel_path.components() {
            let std::path::Component::Normal(seg) = comp else {
                bail!("Invalid output_files component '{}'", rel);
            };
            src_cur.push(seg);
            match std::fs::symlink_metadata(&src_cur) {
                Ok(m) => {
                    if m.file_type().is_symlink() {
                        bail!("Refusing to harvest host_exec output through symlink '{}'", rel);
                    }
                }
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                    missing = true;
                    break;
                }
                Err(e) => return Err(e.into()),
            }
        }
        if missing {
            continue;
        }
        let meta = std::fs::symlink_metadata(&src_cur)?;
        if meta.file_type().is_symlink() || !meta.file_type().is_file() {
            continue;
        }
        if meta.len() > MAX_HOST_EXEC_OUTPUT_HARVEST_BYTES {
            bail!(
                "host_exec output '{}' ({} bytes) exceeds 16 MiB harvest limit",
                rel,
                meta.len()
            );
        }
        let mut opts = std::fs::OpenOptions::new();
        opts.read(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt;
            opts.custom_flags(libc::O_NOFOLLOW);
        }
        let f = opts.open(&src_cur)?;
        let mut bytes = Vec::with_capacity(meta.len() as usize);
        f.take(MAX_HOST_EXEC_OUTPUT_HARVEST_BYTES + 1)
            .read_to_end(&mut bytes)?;
        if (bytes.len() as u64) > MAX_HOST_EXEC_OUTPUT_HARVEST_BYTES {
            bail!("host_exec output '{}' exceeded 16 MiB while reading", rel);
        }

        // Write safely into shadow_root verifying no symlink components on destination.
        let mut dst_cur = canon_shadow.clone();
        let comps: Vec<_> = rel_path.components().collect();
        for comp in &comps[..comps.len().saturating_sub(1)] {
            let std::path::Component::Normal(seg) = comp else {
                bail!("Invalid output destination '{}'", rel);
            };
            dst_cur.push(seg);
            match std::fs::symlink_metadata(&dst_cur) {
                Ok(m) => {
                    if m.file_type().is_symlink() || !m.file_type().is_dir() {
                        bail!(
                            "Refusing to harvest output through symlink or non-directory '{}'",
                            dst_cur.display()
                        );
                    }
                }
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                    std::fs::create_dir(&dst_cur)?;
                }
                Err(e) => return Err(e.into()),
            }
        }
        let dst_file = shadow_root.join(&rel_path);
        if let Ok(m) = std::fs::symlink_metadata(&dst_file) {
            if m.file_type().is_symlink() || m.file_type().is_dir() {
                bail!(
                    "Refusing to overwrite symlink or directory '{}' in shadow",
                    rel
                );
            }
        }
        std::fs::write(&dst_file, &bytes)?;
        harvested.push(json!({
            "path": rel,
            "bytes": bytes.len(),
            "sha256": format!("sha256:{}", hex::encode(Sha256::digest(&bytes))),
        }));
    }
    Ok(harvested)
}

fn scrub_host_exec_output(
    raw: &[u8],
    truncated: bool,
    extra_secrets: &[String],
) -> (String, Vec<String>) {
    let mut text = String::from_utf8_lossy(raw).to_string();
    if truncated {
        text.push_str("\n...[output truncated at 64 KiB]");
    }
    let (mut scrubbed, hits) = redact_dlp_secrets(&text);
    let mut labels: Vec<String> = hits.into_iter().map(str::to_string).collect();
    for secret in extra_secrets {
        let s = secret.trim();
        if s.len() >= 12 && scrubbed.contains(s) {
            scrubbed = scrubbed.replace(s, "[REDACTED_BY_AEGIS_DLP]");
            if !labels.iter().any(|l| l == "DLP:SESSION_CONTROL_TOKEN") {
                labels.push("DLP:SESSION_CONTROL_TOKEN".to_string());
            }
        }
    }
    (scrubbed, labels)
}

